import { coerceNumberProperty } from '@angular/cdk/coercion';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  forwardRef,
  HostBinding,
  inject,
  Input,
  numberAttribute,
  OnInit,
  Output,
  ViewEncapsulation,
} from '@angular/core';
import {
  AbstractControl,
  ControlValueAccessor,
  FormControl,
  FormGroup,
  FormGroupDirective,
  FormsModule,
  NG_VALUE_ACCESSOR,
  ReactiveFormsModule,
  TouchedChangeEvent,
  ValidationErrors,
  ValidatorFn,
  Validators,
} from '@angular/forms';
import { TranslocoModule, TranslocoService } from '@jsverse/transloco';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { range, voidFn } from '@questrade/allspark-angular-components/core/utils';
import { QDropdownComponent } from '@questrade/allspark-angular-components/dropdown';
import { Q_FORM_CONTROL_COMPONENTS } from '@questrade/allspark-angular-components/form-control';
import { QInputDirective } from '@questrade/allspark-angular-components/input';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { takeUntil } from 'rxjs';
import { distinctUntilChanged, filter } from 'rxjs/operators';
import { QDateOfBirthErrorPath } from './types/date-of-birth-error-path.type';

@Component({
  selector: 'q-date-of-birth',
  templateUrl: './date-of-birth.component.html',
  styleUrls: ['./date-of-birth.component.scss'],
  imports: [
    Q_FORM_CONTROL_COMPONENTS,
    QDropdownComponent,
    FormsModule,
    QInputDirective,
    ReactiveFormsModule,
    TranslocoModule,
  ],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QDateOfBirthComponent),
      multi: true,
    },
    QDestroyService,
    MISSING_KEY_HANDLER,
    ALLSPARK_SCOPE,
    FormGroupDirective,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QDateOfBirthComponent implements OnInit, ControlValueAccessor {
  @Output() readonly dayChanged = new EventEmitter<number>();
  @Output() readonly monthChanged = new EventEmitter<number>();
  @Output() readonly yearChanged = new EventEmitter<number>();
  @Output() readonly dateChanged = new EventEmitter<Date>();

  @Input({ transform: numberAttribute }) minAge = 18;
  @Input({ transform: booleanAttribute }) readonly = false;
  @Input() maxAge: number | null = null;
  @Input() customTranslocoPath = '';
  @Input() customErrorPaths: QDateOfBirthErrorPath[] = [];
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-date-of-birth';

  @Input() get day(): number {
    return this._day;
  }
  set day(value: number) {
    if (this._day === value) return;

    this._dateOfBirthFormGroup.controls.day.setValue(coerceNumberProperty(value, null));
    this._day = value;
  }

  @Input() get month(): number {
    return this._month;
  }
  set month(value: number) {
    if (this._month === value) return;

    this._dateOfBirthFormGroup.controls.month.setValue(coerceNumberProperty(value, null));
    this._month = value;
  }

  @Input() get year(): number {
    return this._year;
  }
  set year(value: number) {
    if (this._year === value) return;

    this._dateOfBirthFormGroup.controls.year.setValue(coerceNumberProperty(value, null));
    this._year = value;
  }

  @Input() get disabled(): boolean {
    return this._disabled;
  }
  set disabled(isDisabled: boolean) {
    if (this._disabled === isDisabled) return;

    this._dateOfBirthFormGroup.disable();
    this._disabled = isDisabled;
  }

  @HostBinding('class') hostClass = 'q-dob';

  _months: { label: string; value: number }[] = [];
  _dateOfBirthFormGroup = new FormGroup({
    day: new FormControl<number | null>(null, [Validators.required, Validators.min(1)]),
    month: new FormControl<number | null>(null, [Validators.required]),
    year: new FormControl<number | null>(null, [Validators.required, Validators.min(1)]),
  });
  _translocoCurrentErrorPath = '';

  private _onTouched: () => unknown = voidFn;
  private _onChange: (_: Date) => void = voidFn;
  private _year = 0;
  private _month = 0;
  private _day = 0;
  private _disabled = false;
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _translocoService = inject(TranslocoService);

  ngOnInit(): void {
    this._subscribeToChanges();
    this._setCustomValidators();

    this._translocoService.langChanges$
      .pipe(takeUntil(this._destroy$), distinctUntilChanged())
      .subscribe(() => this._setMonthNames());
  }

  /** @hidden */
  writeValue(dateOfBirth: Date): void {
    if (dateOfBirth) {
      this._dateOfBirthFormGroup.setValue(
        {
          day: dateOfBirth.getDate(),
          month: dateOfBirth.getMonth() + 1,
          year: dateOfBirth.getFullYear(),
        },
        { emitEvent: false },
      );
    }
  }

  /** @hidden */
  registerOnChange(fn: (value: Date) => void): void {
    this._onChange = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  onNumberInput(event: Event, control: FormControl<number | null>): void {
    const target = event.target as HTMLInputElement;
    let inputValue = target.value.slice(0, target.maxLength);

    if (!this._onlyDigits(inputValue)) {
      inputValue = inputValue.replace(/[^0-9]/g, '');
      target.value = inputValue;

      if (inputValue) {
        control.setValue(+inputValue, { emitEvent: false });
      }
    }
  }

  _onMonthFocus(): void {
    this._dateOfBirthFormGroup.controls.month.markAsTouched();
  }

  private _subscribeToChanges(): void {
    this._dateOfBirthFormGroup.valueChanges
      .pipe(takeUntil(this._destroy$), distinctUntilChanged())
      .subscribe(this._handleFormValueChanges.bind(this));

    this._dateOfBirthFormGroup.events
      .pipe(
        takeUntil(this._destroy$),
        filter((event) => event instanceof TouchedChangeEvent),
      )
      .subscribe(this._handleFormTouch.bind(this));
  }

  private _handleFormTouch(): void {
    this._updateDateOfBirthError();
    this._onTouched();
  }

  private _handleFormValueChanges({
    day,
    month,
    year,
  }: Partial<{ day: number | null; month: number | null; year: number | null }>): void {
    const finalDate = this._getValidDateOfBirth(this._dateOfBirthFormGroup as AbstractControl);

    this._handleFormDayChange(day);
    this._handleFormMonthChange(month);
    this._handleFormYearChange(year);
    this._updateAllValueAndValidity();
    this._updateDateOfBirthError();

    if (!finalDate) return;

    this._onChange(finalDate);
    this.dateChanged.emit(finalDate);
  }

  private _handleFormDayChange(value?: number | null): void {
    const day = coerceNumberProperty(value);
    if (!day || this._day === day || !this._onlyDigits(day)) return;

    this._day = day;
    this.dayChanged.emit(day);
  }

  private _handleFormMonthChange(value?: number | null): void {
    const month = coerceNumberProperty(value);
    if (!month || this._month === month) return;

    this._month = month;
    this.monthChanged.emit(month);
  }

  private _handleFormYearChange(value?: number | null): void {
    const year = coerceNumberProperty(value);
    if (!year || this._year === year || !this._onlyDigits(year)) return;

    this._year = year;
    this.yearChanged.emit(year);
  }

  private _updateDateOfBirthError(): void {
    if (this._dateOfBirthFormGroup.untouched) {
      return;
    }

    const translateSlice = 'allspark.dateOfBirth.';
    const translatePath = `${this.customTranslocoPath || translateSlice}`;
    const defaultErrorPaths: QDateOfBirthErrorPath[] = [
      {
        control: this._dateOfBirthFormGroup.controls.day,
        error: 'required',
        path: `${translatePath}requiredDay`,
      },
      {
        control: this._dateOfBirthFormGroup.controls.day,
        error: 'invalidDay',
        path: `${translatePath}invalidDay`,
      },
      {
        control: this._dateOfBirthFormGroup.controls.day,
        error: 'min',
        path: `${translatePath}invalidDay`,
      },
      {
        control: this._dateOfBirthFormGroup.controls.month,
        error: 'required',
        path: `${translatePath}requiredMonth`,
      },
      {
        control: this._dateOfBirthFormGroup.controls.year,
        error: 'required',
        path: `${translatePath}requiredYear`,
      },
      {
        control: this._dateOfBirthFormGroup.controls.year,
        error: 'min',
        path: `${translatePath}invalidYear`,
      },
      {
        control: this._dateOfBirthFormGroup,
        error: 'futureDate',
        path: `${translatePath}futureDate`,
      },
      {
        control: this._dateOfBirthFormGroup,
        error: 'invalidMinAge',
        path: `${translatePath}invalidMinAge`,
      },
      {
        control: this._dateOfBirthFormGroup,
        error: 'invalidMaxAge',
        path: `${translatePath}invalidMaxAge`,
      },
    ];

    const errorPaths = [...defaultErrorPaths, ...this.customErrorPaths];

    for (const { control, error, path } of errorPaths) {
      if (control.touched && control.hasError(error)) {
        // TODO: Remove this once maxYear it's removed from the translation file
        this._translocoCurrentErrorPath =
          this._translocoService.translate(path) === 'allspark.dateOfBirth.futureDate'
            ? `${translatePath}maxYear`
            : path;
        return;
      }
    }
    this._translocoCurrentErrorPath = this._dateOfBirthFormGroup.invalid
      ? `${translatePath}invalidDate`
      : '';
  }

  private _setCustomValidators(): void {
    this._dateOfBirthFormGroup.controls.day.addValidators([this._dayValidator]);
    this._dateOfBirthFormGroup.controls.year.addValidators([this._yearValidator]);
    this._dateOfBirthFormGroup.addValidators([
      this._ageValidator,
      this._futureDateOfBirthValidator,
    ]);

    this._updateAllValueAndValidity();
  }

  private _onlyDigits(value: number | string | null): boolean {
    return /^[0-9]+$/.test(String(value));
  }

  private _getMonthNames(style: 'long' | 'short' | 'narrow'): string[] {
    const activeLanguage = this._translocoService.getActiveLang();
    const dtf = new Intl.DateTimeFormat(activeLanguage, { month: style, timeZone: 'utc' });

    return range(12, (i) => this._format(dtf, new Date(2017, i, 1))) as string[];
  }

  private _setMonthNames(): void {
    this._months = this._getMonthNames('long').map((monthName, index) => ({
      label: monthName,
      value: index + 1,
    }));
  }

  private _format(dtf: Intl.DateTimeFormat, date: Date): string {
    const d = new Date();

    d.setUTCFullYear(date.getFullYear(), date.getMonth(), date.getDate());
    d.setUTCHours(date.getHours(), date.getMinutes(), date.getSeconds(), date.getMilliseconds());

    return dtf.format(d);
  }

  private _dayValidator: ValidatorFn = (
    control: AbstractControl<number>,
  ): ValidationErrors | null => {
    const selectedDay = control.value;
    const daysInTheMonth = new Date(
      this._dateOfBirthFormGroup.controls.year.value || new Date().getFullYear(),
      this._dateOfBirthFormGroup.controls.month.value || new Date().getMonth(),
      0,
    ).getDate();

    if (isNaN(daysInTheMonth)) return null;

    if (!this._onlyDigits(selectedDay)) {
      return { required: true };
    } else if (daysInTheMonth >= selectedDay) {
      return null;
    } else {
      return { invalidDay: true };
    }
  };

  private _yearValidator: ValidatorFn = (
    control: AbstractControl<number>,
  ): ValidationErrors | null => {
    return this._onlyDigits(control.value) ? null : { required: true };
  };

  private _ageValidator: ValidatorFn = (
    control: AbstractControl<number>,
  ): ValidationErrors | null => {
    const validDateOfBirth = this._getValidDateOfBirth(control);
    if (!validDateOfBirth) return null;

    const age = this._calculateAge(validDateOfBirth);

    if (age < this.minAge) {
      return { invalidMinAge: true };
    } else if (this.maxAge && age > this.maxAge) {
      return { invalidMaxAge: true };
    } else {
      return null;
    }
  };

  private _futureDateOfBirthValidator: ValidatorFn = (
    control: AbstractControl<number>,
  ): ValidationErrors | null => {
    const validDateOfBirth = this._getValidDateOfBirth(control);
    if (!validDateOfBirth) return null;

    const today = new Date();

    return validDateOfBirth > today ? { futureDate: true } : null;
  };

  private _getValidDateOfBirth(control: AbstractControl<number>): Date | null {
    const day = control.get('day')?.value;
    const month = control.get('month')?.value;
    const year = control.get('year')?.value;

    if ([day, month, year].some((value) => (value && isNaN(value)) || !value)) return null;

    const birthDate = new Date(year, month - 1, day);

    // Date constructor returns 1900-1999 to values from 0 to 99
    // so we need to update the year to the correct value
    if (year < 100) birthDate.setFullYear(year);

    return birthDate;
  }

  private _calculateAge(dateOfBirth: Date): number {
    const today = new Date();
    const age = today.getFullYear() - dateOfBirth.getFullYear();
    const ageMonth = today.getMonth() - dateOfBirth.getMonth();

    if (ageMonth < 0 || (ageMonth === 0 && today.getDate() < dateOfBirth.getDate())) {
      return age - 1;
    }

    return age;
  }

  private _updateAllValueAndValidity(): void {
    this._dateOfBirthFormGroup.controls.day.updateValueAndValidity({ emitEvent: false });
    this._dateOfBirthFormGroup.controls.month.updateValueAndValidity({ emitEvent: false });
    this._dateOfBirthFormGroup.controls.year.updateValueAndValidity({ emitEvent: false });
    this._dateOfBirthFormGroup.updateValueAndValidity({ emitEvent: false });
  }
}
